		arr_len = r.read_compact_array_len()
	} else {
		arr_len = r.read_array_len()
	}
	mut arr_granting_voters := []LeaderChangeMessageVoter{cap: if arr_len > 0 { arr_len } else { 0 }}
	for _ in 0 .. arr_len {
		mut item_granting_voters := LeaderChangeMessageVoter{}
		item_granting_voters.read_from_versioned(mut r, version, flexible)!
		arr_granting_voters << item_granting_voters
	}
	m.granting_voters = arr_granting_voters
	if flexible {
		num_tags := r.read_uvarint()
		for _ in 0 .. num_tags {
			tag := r.read_uvarint()
			size := int(r.read_uvarint())
			data := r.span(size)
			if r.ok() {
				m.unknown_tags << UnknownTag{
					tag:  tag
					data: data.clone()
				}
			}
		}
	}
	r.complete()!
}
